generated_output:
int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    ParallelDSU dsu(N);

    // Parallelize over rows; inner loop over upper triangle to avoid duplicate edges
    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        std::size_t base = i * N;
        for (std::size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) {
                dsu.unite(static_cast<int>(i), static_cast<int>(j));
            }
        }
    });

    // Find maximum component size
    // First, ensure roots are up-to-date (optional light compression)
    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        (void)dsu.find(static_cast<int>(i));
    });

    // Reduce to max size among roots
    std::atomic<int> max_size{0};
    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        int pi = dsu.parent[i].load(std::memory_order_acquire);
