    using atom_u32 = std::atomic<std::uint32_t>;

    std::vector<atom_sz> parent(N);
    std::vector<atom_u32> rank(N);

    for (size_t i = 0; i < N; ++i) {
        parent[i].store(i, std::memory_order_relaxed);
        rank[i].store(0u, std::memory_order_relaxed);
    }

    auto find = [&](size_t x) {
        while (true) {
            size_t px = parent[x].load(std::memory_order_relaxed);
            if (px == x) return x;
            size_t ppx = parent[px].load(std::memory_order_relaxed);
            // Path halving
            parent[x].compare_exchange_weak(px, ppx, std::memory_order_relaxed);
            x = px;
        }
    };

    auto unite = [&](size_t a, size_t b) {
        while (true) {
            a = find(a);
            b = find(b);
            if (a == b) return;

            auto ra = rank[a].load(std::memory_order_relaxed);
            auto rb = rank[b].load(std::memory_order_relaxed);

            if (ra < rb) {
                std::swap(a, b);
                std::swap(ra, rb);
            }

            // Try to attach b under a
            size_t expected = b;
            if (parent[b].compare_exchange_strong(expected, a, std::memory_order_relaxed)) {
                if (ra == rb) {
                    rank[a].fetch_add(1u, std::memory_order_relaxed);
                }
                return;
            }
            // else: someone else changed parent[b], retry
        }
    };

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j] != 0) {
                unite(i, j);
            }
        }
    });

    std::vector<std::atomic<int>> counts(N);
    for (size_t i = 0; i < N; ++i) counts[i].store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t v) {
        size_t r = find(v);
        counts[r].fetch_add(1, std::memory_order_relaxed);
    });

    int max_sz = 0;
    for (size_t i = 0; i < N; ++i) {
        int c = counts[i].load(std::memory_order_relaxed);
        if (c > max_sz) max_sz = c;
    }
    return max_sz;
}

