        DSU(size_t n) : parent(n), rank(n, 0), m(n) { std::iota(parent.begin(), parent.end(), 0); }
        size_t find(size_t x) const {
            while (parent[x] != x) x = parent[x];
            return x; // no compression to avoid locking overhead
        }
        void unite(size_t u, size_t v) {
            for (;;) {
                size_t ru = find(u), rv = find(v);
                if (ru == rv) return;
