        std::vector<std::mutex> locks;

        DSU(size_t n) : parent(n), rank(n, 0), locks(n) {
            for (size_t i = 0; i < n; ++i) parent[i].store(i, std::memory_order_relaxed);
        }

        size_t find(size_t x) const {
            // Non-compressing find (reads are atomic)
            size_t p = parent[x].load(std::memory_order_acquire);
            while (p != x) {
                x = p;
                p = parent[x].load(std::memory_order_acquire);
            }
            return x;
        }

        void unite(size_t a, size_t b) {
            for (;;) {
                size_t ra = find(a);
                size_t rb = find(b);
                if (ra == rb) return;

                size_t lo = std::min(ra, rb);
                size_t hi = std::max(ra, rb);
                std::scoped_lock<std::mutex, std::mutex> guard(locks[lo], locks[hi]);

                // Re-validate after locking
                ra = find(ra);
