int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<size_t> label(N), new_label(N);
    std::iota(label.begin(), label.end(), 0);

    while (true) {
        std::atomic<bool> changed{false};

        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            size_t minlab = label[i];
            size_t row_off = i * N;
            for (size_t j = 0; j < N; ++j) {
                if (A[row_off + j]) {
                    size_t lj = label[j];
                    if (lj < minlab) minlab = lj;
                }
            }
            new_label[i] = minlab;
        });

        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            if (label[i] != new_label[i]) {
                label[i] = new_label[i];
                changed.store(true, std::memory_order_relaxed);
            }
        });

        if (!changed.load(std::memory_order_relaxed)) break;
    }

    hpx::sort(hpx::execution::par, label.begin(), label.end());

    size_t maxlen = 1, cur = 1;
    for (size_t i = 1; i < N; ++i) {
        if (label[i] == label[i - 1]) {
            ++cur;
        } else {
            if (cur > maxlen) maxlen = cur;
            cur = 1;
        }
    }
    if (N > 0 && cur > maxlen) maxlen = cur;

    return static_cast<int>(maxlen);
}

