int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<int> parent(N), rank(N, 0);
    std::vector<hpx::lcos::local::spinlock> locks(N);
    for (size_t i = 0; i < N; ++i) parent[i] = static_cast<int>(i);

    auto find_root = [&](int x) {
        while (true) {
            int p = parent[x];
            if (p == x) return x;
            x = p;
        }
    };

    auto unite = [&](int u, int v) {
        int ru = find_root(u), rv = find_root(v);
        while (ru != rv) {
            int a = std::min(ru, rv), b = std::max(ru, rv);
            std::scoped_lock<hpx::lcos::local::spinlock, hpx::lcos::local::spinlock> guard(locks[a], locks[b]);
            ru = find_root(ru);
            rv = find_root(rv);
            if (ru == rv) break;
            if (rank[ru] < rank[rv]) std::swap(ru, rv);
            parent[rv] = ru;
            if (rank[ru] == rank[rv]) ++rank[ru];
            break;
        }
    };

    hpx::for_loop(hpx::execution::par, 0, static_cast<long>(N), [&](long i_) {
        size_t i = static_cast<size_t>(i_);
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) unite(static_cast<int>(i), static_cast<int>(j));
        }
    });

    std::vector<std::atomic<int>> counts(N);
    for (auto& c : counts) c.store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, 0, static_cast<long>(N), [&](long i_) {
        int r = find_root(static_cast<int>(i_));
        counts[r].fetch_add(1, std::memory_order_relaxed);
    });

    int max_sz = 0;
    for (size_t i = 0; i < N; ++i)
        max_sz = std::max(max_sz, counts[i].load(std::memory_order_relaxed));

    return max_sz;
}

