int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::atomic<int>> parent(N);
    std::vector<std::atomic<int>> sz(N);
    for (size_t i = 0; i < N; ++i) {
        parent[i].store(static_cast<int>(i), std::memory_order_relaxed);
        sz[i].store(1, std::memory_order_relaxed);
    }

    auto find_root = [&](int x) {
        while (true) {
            int p = parent[x].load(std::memory_order_acquire);
            if (p == x) return x;
            int gp = parent[p].load(std::memory_order_acquire);
            parent[x].compare_exchange_weak(p, gp, std::memory_order_acq_rel);
            x = p;
        }
    };

    auto unite = [&](int u, int v) {
        while (true) {
            int ru = find_root(u);
            int rv = find_root(v);
            if (ru == rv) return;

            int su = sz[ru].load(std::memory_order_acquire);
            int sv = sz[rv].load(std::memory_order_acquire);
            if (su < sv) {
                std::swap(ru, rv);
                std::swap(su, sv);
            }
            int expected = rv;
            if (parent[rv].compare_exchange_strong(expected, ru, std::memory_order_acq_rel)) {
                sz[ru].fetch_add(sv, std::memory_order_acq_rel);
                return;
            }
        }
    };

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) {
                unite(static_cast<int>(i), static_cast<int>(j));
            }
        }
    });

    std::vector<std::atomic<int>> counts(N);
    for (size_t i = 0; i < N; ++i) counts[i].store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        int r = find_root(static_cast<int>(i));
        counts[r].fetch_add(1, std::memory_order_acq_rel);
    });

    int best = 0;
    for (size_t i = 0; i < N; ++i) {
        int c = counts[i].load(std::memory_order_acquire);
        if (c > best) best = c;
    }
    return best;
}

