int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    struct DSU {
        std::vector<std::size_t> parent;
        std::vector<int> sz;
        std::vector<hpx::lcos::local::spinlock> lock;

        DSU(std::size_t n) : parent(n), sz(n, 1), lock(n) {
            std::iota(parent.begin(), parent.end(), 0);
        }

        std::size_t find(std::size_t x) {
            while (true) {
                std::size_t p = parent[x];
                if (p == x) return x;
                x = p;
            }
        }

        void unite(std::size_t a, std::size_t b) {
            while (true) {
                std::size_t ra = find(a);
                std::size_t rb = find(b);
                if (ra == rb) return;

                if (ra > rb) std::swap(ra, rb);

                // Lock in address order to avoid deadlock
                std::scoped_lock<hpx::lcos::local::spinlock,
                                 hpx::lcos::local::spinlock> g(lock[ra], lock[rb]);

                // Re-validate roots after locking
                ra = find(ra);
                rb = find(rb);
                if (ra == rb) continue;

                if (sz[ra] < sz[rb]) std::swap(ra, rb);
                parent[rb] = ra;
                sz[ra] += sz[rb];
                return;
            }
        }
