    std::vector<std::size_t> rows(N);
    std::iota(rows.begin(), rows.end(), 0);

    hpx::for_each(hpx::execution::par, rows.begin(), rows.end(),
                  [&](std::size_t i) {
                      const std::size_t base = i * N;
                      for (std::size_t j = i + 1; j < N; ++j) {
                          if (A[base + j]) dsu.unite(i, j);
                      }
