int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<int> parent(N), comp_size(N, 1);
    std::iota(parent.begin(), parent.end(), 0);
    std::vector<hpx::lcos::local::spinlock> locks(N);

    auto find = [&](int x) {
        int p = parent[x];
        while (p != parent[p]) p = parent[p];
        // Path compression (lock-free)
        while (parent[x] != p) {
            int nx = parent[x];
            parent[x] = p;
            x = nx;
        }
        return p;
    };

    auto unite = [&](int a, int b) {
        for (;;) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;

            int lo = std::min(ra, rb), hi = std::max(ra, rb);
            std::scoped_lock<hpx::lcos::local::spinlock, hpx::lcos::local::spinlock> g(locks[lo], locks[hi]);

            // Re-validate roots under lock
            ra = find(ra);
            rb = find(rb);
            if (ra == rb) return;

            if (comp_size[ra] < comp_size[rb]) std::swap(ra, rb);
            parent[rb] = ra;
            comp_size[ra] += comp_size[rb];
            return;
        }
    };

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        for (size_t j = i + 1; j < N; ++j) {
            if (A[i * N + j]) unite(static_cast<int>(i), static_cast<int>(j));
        }
    });

    int best = 1;
    for (size_t i = 0; i < N; ++i)
        if (parent[i] == static_cast<int>(i))
            best = std::max(best, comp_size[i]);

    return best;
}

