    std::vector<size_t> labels(N), next_labels(N);
    for (size_t i = 0; i < N; ++i) labels[i] = i;

    bool changed = true;
    while (changed) {
        // Compute next labels in parallel: each node takes min label among its neighbors
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
