                std::size_t ra = find(a);
                std::size_t rb = find(b);
                if (ra == rb) return;

                // Lock in address order to avoid deadlock
                std::size_t lo = std::min(ra, rb);
                std::size_t hi = std::max(ra, rb);
                std::unique_lock<hpx::spinlock> g1(lock[lo]);
                std::unique_lock<hpx::spinlock> g2(lock[hi]);

                // Re-validate roots after taking locks
                ra = parent[ra];
                rb = parent[rb];
                if (ra == rb) return;

                if (rank[ra] < rank[rb]) {
                    parent[ra] = rb;
                } else if (rank[ra] > rank[rb]) {
                    parent[rb] = ra;
                } else {
                    parent[rb] = ra;
                    ++rank[ra];
                }
                return;
            }
        }
    };

    DSU dsu(N);

    // Parallel union over upper triangle of adjacency matrix
    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        const std::size_t base = i * N;
        for (std::size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) {
                dsu.unite(i, j);
            }
        }
    });

    // Count component sizes
    std::vector<std::atomic<int>> counts(N);
    for (std::size_t i = 0; i < N; ++i) counts[i].store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        std::size_t r = dsu.find(i);
        counts[r].fetch_add(1, std::memory_order_relaxed);
