int largestComponent(std::vector<int> const& A, size_t N) {
  if (N == 0) return 0;

  struct DSU {
    std::vector<std::atomic<int>> parent;
    std::vector<std::atomic<int>> rank;
    DSU(size_t n) : parent(n), rank(n) {
      for (size_t i = 0; i < n; ++i) { parent[i].store((int)i); rank[i].store(0); }
    }
    int find(int x) {
      int p = parent[x].load(std::memory_order_relaxed);
      while (true) {
        int pp = parent[p].load(std::memory_order_relaxed);
        if (pp == p) break;
        p = pp;
      }
      // path compression
      int curr = x;
      while (true) {
        int pc = parent[curr].load(std::memory_order_relaxed);
        if (pc == p) break;
        parent[curr].store(p, std::memory_order_relaxed);
        curr = pc;
      }
      return p;
    }
    void unite(int a, int b) {
      while (true) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        int rka = rank[ra].load(std::memory_order_relaxed);
        int rkb = rank[rb].load(std::memory_order_relaxed);
        if (rka < rkb) { std::swap(ra, rb); std::swap(rka, rkb); }
        int exp = rb;
        if (parent[rb].compare_exchange_strong(exp, ra, std::memory_order_acq_rel)) {
          if (rka == rkb) rank[ra].fetch_add(1, std::memory_order_relaxed);
          return;
        }
        // else retry
      }
    }
  };

  DSU dsu(N);

  hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
    size_t row = i * N;
    for (size_t j = i + 1; j < N; ++j) {
      if (A[row + j]) dsu.unite((int)i, (int)j);
    }
  });

  std::vector<std::atomic<int>> sizes(N);
  for (size_t i = 0; i < N; ++i) sizes[i].store(0, std::memory_order_relaxed);

  hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
    int r = dsu.find((int)i);
    sizes[(size_t)r].fetch_add(1, std::memory_order_relaxed);
  });

