   output: 2
*/
int largestComponent(std::vector<int> const& A, size_t N) {

generated_output:
int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    // Disjoint-set union with rank and per-node locks
    std::vector<size_t> parent(N);
    std::vector<unsigned> rank(N, 0);
    std::vector<hpx::mutex> locks(N);

    for (size_t i = 0; i < N; ++i) parent[i] = i;

    auto find_root = [&](size_t x) {
        // Path halving (lock-free reads; unions are lock-protected)
        while (parent[x] != x) {
            size_t p = parent[x];
            size_t gp = parent[p];
            parent[x] = gp;
            x = gp;
        }
        return x;
    };

    auto unite = [&](size_t a, size_t b) {
        while (true) {
            size_t ra = find_root(a);
            size_t rb = find_root(b);
            if (ra == rb) return;

            // Lock in id order to avoid deadlock
            size_t l = std::min(ra, rb);
            size_t r = std::max(ra, rb);
            std::scoped_lock<hpx::mutex, hpx::mutex> lk(locks[l], locks[r]);

            // Re-find under lock to validate
            ra = find_root(ra);
            rb = find_root(rb);
            if (ra == rb) return;

            if (rank[ra] < rank[rb]) std::swap(ra, rb);
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) ++rank[ra];
            return;
        }
    };

    // Parallel unite over upper triangle edges
    auto first = hpx::make_counting_iterator<size_t>(0);
    auto last  = hpx::make_counting_iterator<size_t>(N);
    hpx::for_each(hpx::execution::par, first, last, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) unite(i, j);
        }
    });

    // Count component sizes in parallel
    std::vector<std::atomic<size_t>> counts(N);
    for (auto& c : counts) c.store(0, std::memory_order_relaxed);

    hpx::for_each(hpx::execution::par, first, last, [&](size_t i) {
        size_t r = find_root(i);
        counts[r].fetch_add(1, std::memory_order_relaxed);
    });

    // Find maximum
    size_t best = 0;
    for (size_t i = 0; i < N; ++i) {
        best = std::max(best, counts[i].load(std::memory_order_relaxed));
    }
    return static_cast<int>(best);
}

