                sz[i].store(1, std::memory_order_relaxed);
            }
        }

        size_t find(size_t x) {
            size_t p = parent[x].load(std::memory_order_acquire);
            while (p != x) {
                x = p;
                p = parent[x].load(std::memory_order_acquire);
            }
            return x;
        }

        void unite(size_t a, size_t b) {
            for (;;) {
                a = find(a);
                b = find(b);
                if (a == b) return;

                size_t sa = sz[a].load(std::memory_order_relaxed);
                size_t sb = sz[b].load(std::memory_order_relaxed);
