generated_output:
int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::atomic<bool>> visited(N);
    for (auto& v : visited) v.store(false, std::memory_order_relaxed);

    std::atomic<int> global_max{0};
    auto update_max = [&](int val) {
        int cur = global_max.load(std::memory_order_relaxed);
        while (cur < val && !global_max.compare_exchange_weak(cur, val, std::memory_order_relaxed)) {}
    };

    // Build indices 0..N-1
    std::vector<size_t> idx(N);
    std::iota(idx.begin(), idx.end(), size_t{0});

    hpx::ranges::for_each(hpx::execution::par, idx, [&](size_t s) {
        // Try to claim this start vertex
        if (visited[s].exchange(true, std::memory_order_relaxed)) return;

        // BFS from s
        std::queue<size_t> q;
        q.push(s);
        int count = 1;

        while (!q.empty()) {
            size_t u = q.front(); q.pop();
            size_t base = u * N;
            for (size_t v = 0; v < N; ++v) {
                if (A[base + v] != 0) {
                    bool was = visited[v].exchange(true, std::memory_order_relaxed);
                    if (!was) {
                        q.push(v);
                        ++count;
                    }
                }
            }
        }
        update_max(count);
    });

    return global_max.load(std::memory_order_relaxed);
}

