generated_output:
int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    struct DSU {
        std::vector<int> parent;
        std::vector<int> size;
        std::vector<hpx::lcos::local::spinlock> locks;

        DSU(size_t n) : parent(n), size(n, 1), locks(n) {
            for (size_t i = 0; i < n; ++i) parent[i] = static_cast<int>(i);
        }

        int find(int x) const {
            while (parent[x] != x) x = parent[x];
            return x;
        }

        void unite(int a, int b) {
            while (true) {
                int ra = find(a);
                int rb = find(b);
                if (ra == rb) return;

                int lo = std::min(ra, rb);
                int hi = std::max(ra, rb);
                std::scoped_lock<hpx::lcos::local::spinlock, hpx::lcos::local::spinlock> lk(locks[lo], locks[hi]);

                // Re-validate under lock
                ra = find(ra);
                rb = find(rb);
                if (ra == rb) continue;

                if (size[ra] < size[rb]) std::swap(ra, rb);
                parent[rb] = ra;
                size[ra] += size[rb];
                return;
            }
        }
    };

    DSU dsu(N);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        const size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) dsu.unite(static_cast<int>(i), static_cast<int>(j));
        }
    });

    std::vector<std::atomic<int>> counts(N);
    for (size_t i = 0; i < N; ++i) counts[i].store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        int r = dsu.find(static_cast<int>(i));
        counts[r].fetch_add(1, std::memory_order_relaxed);
    });

    int best = 0;
    for (size_t i = 0; i < N; ++i) {
        best = std::max(best, counts[i].load(std::memory_order_relaxed));
    }
    return best;
}

