        std::vector<std::atomic<size_t>> parent;
        std::vector<std::atomic<uint8_t>> rank;
        DSU(size_t n) : parent(n), rank(n) {
            for (size_t i = 0; i < n; ++i) { parent[i].store(i); rank[i].store(0); }
        }
        size_t find(size_t x) {
            size_t p = parent[x].load();
            while (p != parent[p].load()) p = parent[p].load();
            // path compression
            size_t cur = x;
            while (cur != p) {
                size_t next = parent[cur].load();
                parent[cur].store(p);
                cur = next;
            }
            return p;
        }
        void unite(size_t a, size_t b) {
