generated_output:
int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::atomic<char>> visited(N);
    for (auto& v : visited) v.store(0, std::memory_order_relaxed);

    std::mutex max_mtx;
    std::size_t global_max = 0;

    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        if (visited[i].exchange(1, std::memory_order_acq_rel) == 0) {
            std::size_t comp = 0;
            std::vector<std::size_t> stack;
            stack.push_back(i);

            while (!stack.empty()) {
                std::size_t v = stack.back();
                stack.pop_back();
                ++comp;

                std::size_t row = v * N;
                for (std::size_t j = 0; j < N; ++j) {
                    if (A[row + j] && visited[j].exchange(1, std::memory_order_acq_rel) == 0) {
                        stack.push_back(j);
                    }
                }
            }

            std::lock_guard<std::mutex> lk(max_mtx);
            if (comp > global_max) global_max = comp;
        }
    });

    return static_cast<int>(global_max);
}

