int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::size_t> labels(N), next(N);
    std::iota(labels.begin(), labels.end(), 0);

    bool changed;
    do {
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            std::size_t minl = labels[i];
            std::size_t base = i * N;
