int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    // Disjoint-set (union-find) with per-root spinlocks and union by rank (no path compression).
    std::vector<std::atomic<int>> parent(N);
    std::vector<std::atomic<int>> rank(N);
    std::vector<hpx::spinlock> locks(N);

    for (size_t i = 0; i < N; ++i) {
        parent[i].store((int)i, std::memory_order_relaxed);
        rank[i].store(0, std::memory_order_relaxed);
    }

    auto find_root = [&](int x) {
        int p = parent[x].load(std::memory_order_acquire);
        while (p != x) {
            x = p;
            p = parent[x].load(std::memory_order_acquire);
        }
        return p;
    };

    auto unite = [&](int u, int v) {
        while (true) {
            int ru = find_root(u);
            int rv = find_root(v);
            if (ru == rv) return;

            int a = std::min(ru, rv);
            int b = std::max(ru, rv);

            // Lock in order to avoid deadlock
            std::scoped_lock<hpx::spinlock, hpx::spinlock> g(locks[a], locks[b]);

            // Re-validate roots under lock
            ru = find_root(ru);
            rv = find_root(rv);
            if (ru == rv) return;

            int rru = rank[ru].load(std::memory_order_relaxed);
            int rrv = rank[rv].load(std::memory_order_relaxed);

            if (rru < rrv) {
                parent[ru].store(rv, std::memory_order_release);
            } else if (rru > rrv) {
                parent[rv].store(ru, std::memory_order_release);
            } else {
                parent[rv].store(ru, std::memory_order_release);
                rank[ru].store(rru + 1, std::memory_order_relaxed);
            }
            return;
        }
    };

    // Parallel union over upper triangle (i < j) for undirected graph
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t row_off = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[row_off + j]) {
                unite((int)i, (int)j);
            }
        }
    });

    // Count component sizes in parallel
    std::vector<std::atomic<int>> comp_size(N);
    for (size_t i = 0; i < N; ++i) comp_size[i].store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        int r = find_root((int)i);
        comp_size[r].fetch_add(1, std::memory_order_relaxed);
    });

    // Find maximum component size
    int best = 0;
    for (size_t i = 0; i < N; ++i) {
        best = std::max(best, comp_size[i].load(std::memory_order_relaxed));
    }
    return best;
}

