generated_output:
int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::size_t> label(N), new_label(N);
    for (std::size_t i = 0; i < N; ++i) label[i] = i;

    bool changed = true;
    while (changed) {
        std::atomic<bool> any_changed{false};
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            std::size_t minlab = label[i];
            auto const* row = &A[i * N];
            for (std::size_t j = 0; j < N; ++j) {
                if (row[j]) {
                    std::size_t lj = label[j];
                    if (lj < minlab) minlab = lj;
                }
            }
            new_label[i] = minlab;
            if (minlab != label[i]) any_changed.store(true, std::memory_order_relaxed);
        });
        std::swap(label, new_label);
        changed = any_changed.load(std::memory_order_relaxed);
    }

    // Sort labels in parallel, then find the largest run length.
    std::vector<std::size_t> L = label;
    hpx::sort(hpx::execution::par, L.begin(), L.end());

    std::size_t best = 0, cur = 0;
    for (std::size_t i = 0; i < L.size(); ) {
        std::size_t j = i + 1;
        while (j < L.size() && L[j] == L[i]) ++j;
        cur = j - i;
        if (cur > best) best = cur;
        i = j;
    }
    return static_cast<int>(best);
}

