generated_output:
int largestComponent(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<int> parent(N), rank(N, 0);
    std::vector<hpx::lcos::local::spinlock> locks(N);
    for (size_t i = 0; i < N; ++i) parent[i] = static_cast<int>(i);

    auto find = [&](int x) {
        while (true) {
            int p = parent[x];
            if (p == x) return x;
            int gp = parent[p];
            if (gp != p) parent[x] = gp; // path halving (benign races ok)
            x = p;
        }
    };

    auto unite = [&](int a, int b) {
        while (true) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;

            int l = std::min(ra, rb);
            int r = std::max(ra, rb);
            std::scoped_lock<hpx::lcos::local::spinlock,
                             hpx::lcos::local::spinlock> g(locks[l], locks[r]);

            // re-validate roots under lock
            ra = find(ra);
            rb = find(rb);
            if (ra == rb) return;

            if (rank[ra] < rank[rb]) std::swap(ra, rb);
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) ++rank[ra];
            return;
        }
    };

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j] != 0) unite(static_cast<int>(i),
                                        static_cast<int>(j));
        }
    });

    std::vector<std::atomic<int>> comp_size(N);
    for (auto& x : comp_size) x.store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        int r = find(static_cast<int>(i));
        comp_size[r].fetch_add(1, std::memory_order_relaxed);
    });

    int best = 0;
    for (size_t i = 0; i < N; ++i)
        best = std::max(best, comp_size[i].load(std::memory_order_relaxed));
    return best;
}

