    std::vector<std::size_t> comp_size(N, 1);
    std::vector<hpx::mutex> locks(N);

    auto find_root = [&](std::size_t x) {
        while (true) {
            std::size_t p = parent[x];
            if (p == x) return x;
            x = p;
        }
    };

    auto unite = [&](std::size_t a, std::size_t b) {
        while (true) {
            std::size_t ra = find_root(a);
            std::size_t rb = find_root(b);
            if (ra == rb) return;

            std::size_t lo = std::min(ra, rb);
            std::size_t hi = std::max(ra, rb);
            std::scoped_lock<hpx::mutex, hpx::mutex> lk(locks[lo], locks[hi]);

            // Re-validate after locking
            ra = find_root(ra);
            rb = find_root(rb);
            if (ra == rb) return;

            // Union by size: attach smaller to larger
            if (comp_size[ra] < comp_size[rb]) std::swap(ra, rb);
