        std::size_t base = i * N;
        for (std::size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) unite(i, j);
        }
    });

    return hpx::transform_reduce(
        hpx::execution::par,
        parent.begin(), parent.end(),
        std::size_t(0),
        [](std::size_t a, std::size_t b) { return std::max(a, b); },
        [&](std::size_t idx) {
            // A root is a node that is its own parent
            return parent[idx] == idx ? comp_size[idx] : std::size_t(0);
        }
    );
}

