int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;
    using hpx::execution::par;
    using hpx::util::counting_iterator;

    auto first = counting_iterator<size_t>(0);
    auto last  = counting_iterator<size_t>(N);

    auto row_sum = [&A, N](size_t i) {
        size_t off = i * N;
        return std::accumulate(A.begin() + off, A.begin() + off + N, 0);
    };

    return hpx::transform_reduce(
        par, first, last, 0,
        [](int a, int b) { return std::max(a, b); },
        row_sum
    );
}

