generated_output:
{
    if (N == 0) return 0;

    std::size_t num_tasks = hpx::get_os_thread_count();
    if (num_tasks == 0) num_tasks = 1;
    num_tasks = std::min<std::size_t>(num_tasks, N);
    std::size_t chunk = (N + num_tasks - 1) / num_tasks;

    std::vector<hpx::future<int>> fs;
    fs.reserve(num_tasks);

    for (std::size_t t = 0; t < num_tasks; ++t) {
        std::size_t begin = t * chunk;
        if (begin >= N) break;
        std::size_t end = std::min<std::size_t>(begin + chunk, N);

        fs.emplace_back(hpx::async([begin, end, &A, N]() -> int {
            int local_max = 0;
            for (std::size_t i = begin; i < end; ++i) {
                const std::size_t off = i * N;
                int deg = 0;
                for (std::size_t j = 0; j < N; ++j) {
                    deg += A[off + j];
                }
                if (deg > local_max) local_max = deg;
            }
            return local_max;
        }));
    }

    int maxdeg = 0;
    for (auto& f : fs) {
        int d = f.get();
        if (d > maxdeg) maxdeg = d;
    }
    return maxdeg;
}

