int maxDegree(std::vector<int> const& A, size_t N) {
    std::atomic<int> maxdeg{0};

    hpx::for_loop(hpx::execution::par, size_t{0}, N, [&](size_t i) {
        int sum = 0;
        size_t base = i * N;
        for (size_t j = 0; j < N; ++j) sum += A[base + j];

        int prev = maxdeg.load(std::memory_order_relaxed);
        while (prev < sum &&
               !maxdeg.compare_exchange_weak(prev, sum,
                                             std::memory_order_relaxed,
                                             std::memory_order_relaxed)) {}
    });

    return maxdeg.load(std::memory_order_relaxed);
}

