    auto last  = hpx::make_counting_iterator<size_t>(N);

    auto degree_of = [&](size_t i) {
        size_t base = i * N;
        int sum = 0;
        for (size_t j = 0; j < N; ++j) sum += A[base + j];
        // exclude possible self-loop
        return sum - A[base + i];
    };

    return hpx::transform_reduce(
        hpx::execution::par, first, last, 0,
        hpx::max<int>(), degree_of
    );
}

