int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<int> deg(N, 0);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        auto row_begin = A.begin() + i * N;
        auto row_end   = row_begin + N;
        deg[i] = std::accumulate(row_begin, row_end, 0);
    });

    return hpx::reduce(hpx::execution::par, deg.begin(), deg.end(), 0, hpx::max<int>());
}

