    };

    auto union_sets = [&](size_t u, size_t v) {
        for (;;) {
            size_t ru = find_root(u);
            size_t rv = find_root(v);
            if (ru == rv) return;

            size_t a = std::min(ru, rv);
            size_t b = std::max(ru, rv);

            std::unique_lock<hpx::spinlock> la(locks[a]);
            std::unique_lock<hpx::spinlock> lb(locks[b]);

            // Re-validate after locking
            ru = find_root(ru);
            rv = find_root(rv);
            if (ru == rv) return;

            // Reorder after re-validate
            if (ru > rv) std::swap(ru, rv);

