int componentCount(std::vector<int> const& A, std::size_t N) {
    if (N == 0) return 0;

    std::vector<std::atomic<std::size_t>> label(N);
    for (std::size_t i = 0; i < N; ++i) label[i].store(i, std::memory_order_relaxed);

    // Parallel label propagation until convergence
    bool changed;
    do {
        std::atomic<bool> any_changed{false};
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
