            size_t ry = find_root(y);
            if (rx == ry) return;
            size_t hi = rx > ry ? rx : ry;
            size_t lo = rx ^ ry ^ hi; // the other one
            size_t expected = hi;
            if (parent[hi].compare_exchange_strong(expected, lo, std::memory_order_relaxed)) {
                return;
