        tasks.push_back(hpx::async([&, i] {
            size_t row_off = i * N;
            for (size_t j = i + 1; j < N; ++j) {
                if (A[row_off + j]) {
                    unite(i, j);
                }
            }
        }));
    }
    hpx::wait_all(tasks);

    // Final path compression in parallel
    tasks.clear();
    tasks.reserve(N);
    for (size_t i = 0; i < N; ++i) {
