int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<size_t> parent(N), rank(N, 0);
    std::vector<std::mutex> locks(N);
    for (size_t i = 0; i < N; ++i) parent[i] = i;

    auto find_root = [&](size_t x) {
        while (true) {
            size_t p = parent[x];
            if (p == x) return x;
            x = p;
        }
    };

    auto unite = [&](size_t u, size_t v) {
        for (;;) {
            size_t ru = find_root(u);
            size_t rv = find_root(v);
            if (ru == rv) return;

            size_t a = std::min(ru, rv), b = std::max(ru, rv);
            std::scoped_lock<std::mutex, std::mutex> lk(locks[a], locks[b]);

            // Re-validate roots after locking
            if (parent[ru] != ru || parent[rv] != rv) continue;

            if (rank[ru] < rank[rv]) std::swap(ru, rv);
            parent[rv] = ru;
            if (rank[ru] == rank[rv]) ++rank[ru];
            return;
        }
    };

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) unite(i, j);
        }
    });

    // Compress and count unique roots
    for (size_t i = 0; i < N; ++i) {
        parent[i] = find_root(i);
    }
    std::unordered_set<size_t> roots(parent.begin(), parent.end());
    return static_cast<int>(roots.size());
}

