{
    using hpx::execution::par;

    // Disjoint-set with lock-free-ish union by rank using atomics
    std::vector<std::atomic<size_t>> parent(N);
    std::vector<std::atomic<int>> rank(N);
    for (size_t i = 0; i < N; ++i) {
        parent[i].store(i, std::memory_order_relaxed);
        rank[i].store(0, std::memory_order_relaxed);
    }

    auto find = [&](size_t x) {
        // Find with path compression using atomics
        size_t px = parent[x].load(std::memory_order_acquire);
        while (true) {
            size_t ppx = parent[px].load(std::memory_order_acquire);
            if (ppx == px) break;
            px = ppx;
        }
        size_t root = px;

        // Path compression
        size_t cur = x;
        while (true) {
            size_t p = parent[cur].load(std::memory_order_acquire);
            if (p == root) break;
            parent[cur].store(root, std::memory_order_release);
            cur = p;
        }
        return root;
    };

    auto unite = [&](size_t a, size_t b) {
        while (true) {
            size_t ra = find(a);
            size_t rb = find(b);
            if (ra == rb) return;

            // Union by rank with CAS on parent of rb
            // Ensure deterministic locking order by rank/idx
            if (rank[ra].load(std::memory_order_relaxed) < rank[rb].load(std::memory_order_relaxed) ||
                (rank[ra].load(std::memory_order_relaxed) == rank[rb].load(std::memory_order_relaxed) && ra > rb)) {
                std::swap(ra, rb);
            }

            size_t expected = rb;
            if (parent[rb].compare_exchange_strong(expected, ra, std::memory_order_acq_rel)) {
                if (rank[ra].load(std::memory_order_relaxed) ==
                    rank[rb].load(std::memory_order_relaxed)) {
                    rank[ra].fetch_add(1, std::memory_order_relaxed);
                }
                return;
            }
            // else: someone else linked rb, retry
        }
    };

    // Parallel union all edges (only upper triangle i<j)
    hpx::for_loop(par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j] != 0) {
                unite(i, j);
            }
        }
    });

    // Count roots in parallel
    auto is_root = [&](size_t i) -> int {
        return find(i) == i ? 1 : 0;
    };

    int components = hpx::transform_reduce(
        par,
        size_t(0), N,
        0,
        std::plus<int>{},
        is_root
    );

    return components;
}

