generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    struct DSU {
        std::vector<int> parent;
        std::vector<int> rank;
        std::vector<hpx::spinlock> locks;

        DSU(size_t n) : parent(n), rank(n, 0), locks(n) {
            for (size_t i = 0; i < n; ++i) parent[i] = static_cast<int>(i);
        }

        int find(int x) const noexcept {
            // Non-locking find (no path compression for simplicity/safety)
            while (parent[x] != x) x = parent[x];
            return x;
        }

        void unite(int x, int y) {
            while (true) {
                int rx = find(x);
                int ry = find(y);
                if (rx == ry) return;

                int a = std::min(rx, ry);
                int b = std::max(rx, ry);

                std::scoped_lock<hpx::spinlock, hpx::spinlock> g(locks[a], locks[b]);

                // Re-validate roots under lock
                rx = find(rx);
                ry = find(ry);
                if (rx == ry) return;

                if (rank[rx] < rank[ry]) std::swap(rx, ry);
                parent[ry] = rx;
                if (rank[rx] == rank[ry]) ++rank[rx];
                return;
            }
        }
    };

    DSU dsu(N);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j] != 0) dsu.unite(static_cast<int>(i), static_cast<int>(j));
        }
    });

    // Mark roots in parallel
    std::vector<std::atomic<char>> is_root(N);
    for (auto& v : is_root) v.store(0, std::memory_order_relaxed);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        int r = dsu.find(static_cast<int>(i));
        is_root[static_cast<size_t>(r)].store(1, std::memory_order_relaxed);
    });

    // Count roots
    int count = 0;
    for (size_t i = 0; i < N; ++i) if (is_root[i].load(std::memory_order_relaxed)) ++count;
    return count;
}

