generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    struct DSU {
        std::vector<std::atomic<int>> parent;
        std::vector<std::atomic<int>> rank;

        DSU(size_t n) : parent(n), rank(n) {
            for (size_t i = 0; i < n; ++i) {
                parent[i].store(static_cast<int>(i), std::memory_order_relaxed);
                rank[i].store(0, std::memory_order_relaxed);
            }
        }

        int find(int x) {
            int p = parent[x].load(std::memory_order_acquire);
            while (p != x) {
                x = p;
                p = parent[x].load(std::memory_order_acquire);
            }
            return x;
        }

        void unite(int a, int b) {
            for (;;) {
                int ra = find(a);
                int rb = find(b);
                if (ra == rb) return;

                int rra = rank[ra].load(std::memory_order_acquire);
                int rrb = rank[rb].load(std::memory_order_acquire);

                // Ensure ra is the higher-rank root
                if (rra < rrb) {
                    std::swap(ra, rb);
                    std::swap(rra, rrb);
                }

                int expected = rb;
                // Try to link rb -> ra
                if (parent[rb].compare_exchange_strong(expected, ra, std::memory_order_acq_rel)) {
                    if (rra == rrb) {
                        rank[ra].fetch_add(1, std::memory_order_acq_rel);
                    }
                    return;
                }
                // else: someone else linked rb; retry
            }
        }
    };

    DSU dsu(N);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j] != 0) {
                dsu.unite(static_cast<int>(i), static_cast<int>(j));
            }
        }
    });

    int count = 0;
    for (size_t i = 0; i < N; ++i) {
        if (dsu.parent[i].load(std::memory_order_acquire) == static_cast<int>(i)) {
            ++count;
        }
    }
    return count;
}

