generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    // Concurrent DSU (union-find) with per-root spinlocks
    std::vector<std::atomic<size_t>> parent(N);
    std::vector<std::atomic<unsigned>> rank(N);
    std::vector<hpx::lcos::local::spinlock> locks(N);

    for (size_t i = 0; i < N; ++i) {
        parent[i].store(i, std::memory_order_relaxed);
        rank[i].store(0u, std::memory_order_relaxed);
    }

    auto find_nolock = [&](size_t x) {
        while (true) {
            size_t p = parent[x].load(std::memory_order_acquire);
            if (p == x) return x;
            x = p;
        }
    };

    auto unite = [&](size_t a, size_t b) {
        for (;;) {
            a = find_nolock(a);
            b = find_nolock(b);
            if (a == b) return;

            size_t lo = std::min(a, b);
            size_t hi = std::max(a, b);

            std::scoped_lock<hpx::lcos::local::spinlock, hpx::lcos::local::spinlock> lk(locks[lo], locks[hi]);

            // Re-validate after locking
            a = find_nolock(a);
            b = find_nolock(b);
            if (a == b) return;

            unsigned ra = rank[a].load(std::memory_order_relaxed);
            unsigned rb = rank[b].load(std::memory_order_relaxed);

            if (ra < rb) std::swap(a, b), std::swap(ra, rb);

            parent[b].store(a, std::memory_order_release);
            if (ra == rb) {
                rank[a].store(ra + 1, std::memory_order_relaxed);
            }
            return;
        }
    };

    // Parallel over upper triangle edges
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) {
                unite(i, j);
            }
        }
    });

    // Count roots
    return static_cast<int>(hpx::transform_reduce(
        hpx::execution::par, size_t(0), N, size_t(0),
        std::plus<size_t>{},
        [&](size_t i) -> size_t {
            return parent[i].load(std::memory_order_acquire) == i ? 1u : 0u;
        }));
}

