    // Disjoint-set union (union-find) with per-root spinlocks
    std::vector<size_t> parent(N);
    std::vector<unsigned> rank(N, 0);
    std::vector<hpx::lcos::local::spinlock> locks(N);

    for (size_t i = 0; i < N; ++i) parent[i] = i;

    auto find_root = [&](size_t x) {
        while (true) {
            size_t p = parent[x];
            if (p == x) return x;
            x = p;
        }
    };

    auto unite = [&](size_t a, size_t b) {
        while (true) {
            size_t ra = find_root(a);
            size_t rb = find_root(b);
            if (ra == rb) return;

            size_t lo = std::min(ra, rb);
            size_t hi = std::max(ra, rb);

            std::scoped_lock<hpx::lcos::local::spinlock,
                             hpx::lcos::local::spinlock> guard(locks[lo], locks[hi]);

            // Re-validate after locking
            ra = find_root(ra);
            rb = find_root(rb);
            if (ra == rb) return;

            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                ++rank[ra];
