    std::atomic<int> count{0};
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        if (find_root(i) == i) count.fetch_add(1, std::memory_order_relaxed);
    });

    return count.load(std::memory_order_relaxed);
}

