int componentCount(std::vector<int> const& A, size_t N) {
  if (N == 0) return 0;

  std::vector<std::size_t> label(N), next(N);
  for (std::size_t i = 0; i < N; ++i) label[i] = i;

  // Label propagation until convergence
  for (;;) {
    std::atomic<bool> any_changed{false};

    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
      std::size_t li = label[i];
      const int* row = &A[i * N];
      for (std::size_t j = 0; j < N; ++j) {
        if (row[j]) {
          std::size_t lj = label[j];
          if (lj < li) li = lj;
        }
      }
      next[i] = li;
    });

    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
      if (next[i] != label[i]) {
        label[i] = next[i];
        any_changed.store(true, std::memory_order_relaxed);
      }
    });

    if (!any_changed.load(std::memory_order_relaxed)) break;
  }

  std::unordered_set<std::size_t> uniq(label.begin(), label.end());
  return static_cast<int>(uniq.size());
}

