generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
  if (N == 0) return 0;

  // Concurrent union-find (lock-free, no path compression)
  std::vector<hpx::atomic<size_t>> parent(N);
  for (size_t i = 0; i < N; ++i) parent[i].store(i, std::memory_order_relaxed);

  auto find_root = [&](size_t x) {
    size_t p = parent[x].load(std::memory_order_acquire);
    while (true) {
      size_t pp = parent[p].load(std::memory_order_acquire);
      if (p == pp) return p;
      p = pp;
    }
  };

  auto unite = [&](size_t a, size_t b) {
    while (true) {
      size_t ra = find_root(a);
      size_t rb = find_root(b);
      if (ra == rb) return;
      size_t hi = ra > rb ? ra : rb;
      size_t lo = ra > rb ? rb : ra;
      size_t expected = hi;
      if (parent[hi].compare_exchange_strong(expected, lo, std::memory_order_acq_rel))
        return;
      // else retry
    }
  };

  hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
    size_t base = i * N;
    for (size_t j = i + 1; j < N; ++j) {
      if (A[base + j]) unite(i, j);
    }
  });

  std::vector<size_t> roots(N);
  hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
    roots[i] = find_root(i);
  });

  hpx::sort(hpx::execution::par, roots.begin(), roots.end());
  int components = 0;
  size_t last = N ? roots[0] : 0;
  for (size_t i = 0; i < N; ++i) {
    if (i == 0 || roots[i] != last) {
      ++components;
      last = roots[i];
    }
  }
  return components;
}

