int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::atomic<size_t>> parent(N);
    std::vector<std::atomic<uint8_t>> rank(N);
    for (size_t i = 0; i < N; ++i) {
        parent[i].store(i, std::memory_order_relaxed);
        rank[i].store(0, std::memory_order_relaxed);
    }

    auto find = [&](size_t x) {
        size_t p = parent[x].load(std::memory_order_acquire);
        while (true) {
            size_t gp = parent[p].load(std::memory_order_acquire);
            if (p == gp) return p;
            // path splitting
            parent[x].compare_exchange_weak(p, gp, std::memory_order_acq_rel);
            x = p;
            p = parent[x].load(std::memory_order_acquire);
        }
    };

    auto unite = [&](size_t a, size_t b) {
        while (true) {
            a = find(a);
            b = find(b);
            if (a == b) return;

            uint8_t ra = rank[a].load(std::memory_order_acquire);
            uint8_t rb = rank[b].load(std::memory_order_acquire);
            if (ra < rb) std::swap(a, b), std::swap(ra, rb);

            size_t expected = b;
            if (parent[b].compare_exchange_strong(expected, a, std::memory_order_acq_rel)) {
                if (ra == rb) rank[a].fetch_add(1, std::memory_order_acq_rel);
                return;
            }
            // else retry with updated parents
        }
    };

    std::vector<size_t> rows(N);
    std::iota(rows.begin(), rows.end(), 0);

    hpx::for_each(hpx::execution::par, rows.begin(), rows.end(),
                  [&](size_t i) {
                      const size_t base = i * N;
                      for (size_t j = i + 1; j < N; ++j) {
                          if (A[base + j]) unite(i, j);
                      }
                  });

    int count = 0;
    for (size_t i = 0; i < N; ++i) {
        if (find(i) == i) ++count;
    }
    return count;
}

