    explicit DSU(size_t n) : parent(n), rank(n) {
      for (size_t i = 0; i < n; ++i) {
        parent[i].store((int)i, std::memory_order_relaxed);
        rank[i].store(0, std::memory_order_relaxed);
      }
    }

    int find(int x) {
      for (;;) {
        int p = parent[x].load(std::memory_order_relaxed);
        if (p == x) return x;
        int gp = parent[p].load(std::memory_order_relaxed);
        parent[x].compare_exchange_weak(p, gp, std::memory_order_relaxed);
        x = p;
      }
    }

    void unite(int a, int b) {
      for (;;) {
        a = find(a);
        b = find(b);
        if (a == b) return;

        int ra = rank[a].load(std::memory_order_relaxed);
        int rb = rank[b].load(std::memory_order_relaxed);
        if (ra < rb) std::swap(a, b);

        int expected = b;
        if (parent[b].compare_exchange_strong(expected, a, std::memory_order_acq_rel)) {
          if (ra == rb) rank[a].fetch_add(1, std::memory_order_relaxed);
          return;
        }
      }
    }
  };

  DSU dsu(N);

  hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
    const size_t base = i * N;
    for (size_t j = i + 1; j < N; ++j) {
      if (A[base + j]) dsu.unite((int)i, (int)j);
    }
  });

  std::vector<int> roots(N);
  hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
    roots[i] = dsu.find((int)i);
  });

  hpx::sort(hpx::execution::par, roots.begin(), roots.end());
  auto it = std::unique(roots.begin(), roots.end());
  return (int)std::distance(roots.begin(), it);
}

