int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::atomic<bool>> visited(N);
    for (size_t i = 0; i < N; ++i) visited[i].store(false, std::memory_order_relaxed);

    std::atomic<int> components{0};

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t u) {
        if (!visited[u].exchange(true, std::memory_order_acq_rel)) {
            components.fetch_add(1, std::memory_order_relaxed);

            std::vector<size_t> frontier;
            frontier.push_back(u);

            while (!frontier.empty()) {
                std::vector<size_t> next;
                hpx::mutex next_mtx;

                hpx::for_each(hpx::execution::par, frontier.begin(), frontier.end(),
                              [&](size_t x) {
                    std::vector<size_t> local_next;
                    size_t row = x * N;

                    for (size_t v = 0; v < N; ++v) {
                        if (A[row + v]) {
                            if (!visited[v].exchange(true, std::memory_order_acq_rel)) {
                                local_next.push_back(v);
                            }
                        }
                    }

                    if (!local_next.empty()) {
                        std::lock_guard<hpx::mutex> lk(next_mtx);
                        next.insert(next.end(), local_next.begin(), local_next.end());
                    }
                });

                frontier.swap(next);
            }
        }
    });

    return components.load(std::memory_order_relaxed);
}

