int componentCount(std::vector<int> const& A, size_t N) {
    using hpx::execution::par;
    using hpx::execution::seq;

    if (N == 0) return 0;

    std::vector<std::atomic<size_t>> parent(N);
    std::vector<unsigned char> rank(N, 0);
    std::vector<hpx::spinlock> locks(N);

    for (size_t i = 0; i < N; ++i) parent[i].store(i, std::memory_order_relaxed);

    auto find = [&](size_t x) {
        size_t p = parent[x].load(std::memory_order_relaxed);
        while (p != x) {
            size_t gp = parent[p].load(std::memory_order_relaxed);
            parent[x].store(gp, std::memory_order_relaxed); // path halving
            x = p;
            p = gp;
        }
        return x;
    };

    auto unite = [&](size_t u, size_t v) {
        for (;;) {
            size_t ru = find(u);
            size_t rv = find(v);
            if (ru == rv) return;

            size_t a = std::min(ru, rv);
            size_t b = std::max(ru, rv);

            std::scoped_lock<hpx::spinlock, hpx::spinlock> g(locks[a], locks[b]);

            // Re-validate after locking
            ru = find(ru);
            rv = find(rv);
            if (ru == rv) return;

            if (rank[ru] < rank[rv]) std::swap(ru, rv);

            parent[rv].store(ru, std::memory_order_relaxed);
            if (rank[ru] == rank[rv]) ++rank[ru];
            return;
        }
    };

    // Parallel over rows; process only upper triangle (i < j)
    hpx::for_loop(par, size_t(0), N, [&](size_t i) {
        size_t row = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[row + j]) {
                unite(i, j);
            }
        }
    });

    // Count roots
    std::atomic<int> count{0};
    hpx::for_loop(par, size_t(0), N, [&](size_t i) {
        if (find(i) == i) count.fetch_add(1, std::memory_order_relaxed);
    });

    return count.load(std::memory_order_relaxed);
}

