   output: 2
*/
int componentCount(std::vector<int> const& A, size_t N) {

generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
    std::vector<std::atomic<unsigned char>> visited(N);
    for (auto& v : visited) v.store(0, std::memory_order_relaxed);

    auto try_mark = [&](size_t i) -> bool {
        unsigned char expected = 0;
        return visited[i].compare_exchange_strong(expected, (unsigned char)1, std::memory_order_acq_rel);
    };

    std::vector<hpx::future<int>> tasks;
    tasks.reserve(N);

    for (size_t v = 0; v < N; ++v) {
        tasks.push_back(hpx::async([v, N, &A, try_mark]() mutable -> int {
            if (!try_mark(v)) return 0;  // already claimed by another search
            std::vector<size_t> stack;
            stack.push_back(v);
            while (!stack.empty()) {
                size_t u = stack.back(); stack.pop_back();
                size_t row = u * N;
                for (size_t j = 0; j < N; ++j) {
                    if (A[row + j] != 0) {
                        if (try_mark(j)) stack.push_back(j);
                    }
                }
            }
            return 1;  // this task discovered a new component
        }));
    }

    int components = 0;
    for (auto& f : tasks) components += f.get();
    return components;
}

