int componentCount(std::vector<int> const& A, size_t N) {
  if (N == 0) return 0;

  std::vector<std::atomic<size_t>> parent(N);
  std::vector<std::atomic<uint8_t>> rank(N);
  for (size_t i = 0; i < N; ++i) {
    parent[i].store(i, std::memory_order_relaxed);
    rank[i].store(0, std::memory_order_relaxed);
  }

  auto find_root = [&](size_t x) {
    size_t p = parent[x].load(std::memory_order_acquire);
    while (p != parent[p].load(std::memory_order_acquire)) {
      p = parent[p].load(std::memory_order_acquire);
    }
    // Path compression
    size_t cur = x;
    while (cur != p) {
      size_t next = parent[cur].load(std::memory_order_acquire);
      parent[cur].store(p, std::memory_order_release);
      cur = next;
    }
    return p;
  };

  auto unite = [&](size_t a, size_t b) {
    for (;;) {
      size_t ra = find_root(a);
      size_t rb = find_root(b);
      if (ra == rb) return;

      uint8_t rra = rank[ra].load(std::memory_order_acquire);
      uint8_t rrb = rank[rb].load(std::memory_order_acquire);

      size_t high = ra, low = rb;
      bool inc_rank = false;
      if (rra < rrb) { high = rb; low = ra; }
      else if (rra > rrb) { high = ra; low = rb; }
      else { high = ra; low = rb; inc_rank = (ra != rb); }

      size_t expected = low;
      if (parent[low].compare_exchange_strong(expected, high, std::memory_order_acq_rel)) {
        if (inc_rank) {
          // Only safe to increment if we actually linked equal-rank roots
          rank[high].fetch_add(1, std::memory_order_acq_rel);
        }
        return;
      }
      // CAS failed due to race; retry
    }
  };

  auto policy = hpx::execution::par;

  // Parallelly process upper triangle (avoid duplicate edges and self-loops)
  hpx::for_loop(policy, size_t(0), N, [&](size_t i) {
    size_t base = i * N;
    for (size_t j = i + 1; j < N; ++j) {
