  std::vector<size_t> flags(N, 0);
  hpx::for_loop(policy, size_t(0), N, [&](size_t i) {
    if (find_root(i) == i) flags[i] = 1;
  });
  return hpx::reduce(policy, flags.begin(), flags.end(), size_t(0));
