    parent[i].store(i, std::memory_order_relaxed);
    rank[i].store(0, std::memory_order_relaxed);
  }

  auto find_root = [&](size_t x) {
    size_t p = parent[x].load(std::memory_order_acquire);
    while (p != parent[p].load(std::memory_order_acquire)) {
      p = parent[p].load(std::memory_order_acquire);
    }
    // Path compression
    size_t cur = x;
    while (cur != p) {
      size_t next = parent[cur].load(std::memory_order_acquire);
      parent[cur].store(p, std::memory_order_release);
