                parent[x].store(gp, std::memory_order_release); // path halving on x
                x = p;
                p = parent[x].load(std::memory_order_acquire);
            }
            return p;
        }

        void unite(int a, int b) {
            for (;;) {
                int ra = find(a);
                int rb = find(b);
                if (ra == rb) return;

