      if (gp != p) {
        // Try to make x point to grandparent to halve path.
        parent[x].compare_exchange_weak(p, gp, std::memory_order_relaxed, std::memory_order_relaxed);
      }
      x = p;
      p = parent[x].load(std::memory_order_relaxed);
    }
    return x;
  };

