    for (;;) {
      int ra = find_root(a);
      int rb = find_root(b);
      if (ra == rb) return;
      // Attach higher index to lower index to break ties deterministically.
      int hi = ra > rb ? ra : rb;
      int lo = ra ^ rb ^ hi; // the other one
      int expected = hi;
      if (parent[hi].compare_exchange_strong(expected, lo, std::memory_order_relaxed)) return;
      // else: someone raced, retry
