    for (auto& v : visited) v.store(0, std::memory_order_relaxed);

    int components = 0;
    std::vector<size_t> frontier, next;
    std::mutex next_mtx;

    for (size_t i = 0; i < N; ++i) {
        if (visited[i].load(std::memory_order_acquire) == 0 &&
