                rank[i].store(0, std::memory_order_relaxed);
            }
        }

        size_t find_root(size_t u) const {
            for (;;) {
                size_t p = parent[u].load(std::memory_order_acquire);
                if (p == u) return u;
                u = p;
            }
        }

        void unite(size_t u, size_t v) {
            for (;;) {
                size_t ru = find_root(u);
                size_t rv = find_root(v);
                if (ru == rv) return;

