            for (size_t j = i + 1; j < N; ++j) {
                if (A[i * N + j]) unite(static_cast<int>(i), static_cast<int>(j));
            }
        }));
    }
    hpx::when_all(tasks).wait();

    int components = 0;
    for (size_t i = 0; i < N; ++i) {
        if (find(find, static_cast<int>(i)) == static_cast<int>(i)) ++components;
