    std::vector<std::atomic<int>> parent(N);
    for (size_t i = 0; i < N; ++i) parent[i].store(-1, std::memory_order_relaxed);

    // Per-node spinlocks to synchronize unions
    std::vector<hpx::lcos::local::spinlock> locks(N);

    auto find_root = [&](size_t x) {
        // No path compression to keep it simple thread-safe
        int p = parent[x].load(std::memory_order_acquire);
        while (p >= 0) {
            x = static_cast<size_t>(p);
            p = parent[x].load(std::memory_order_acquire);
        }
        return x;
    };

    auto unite = [&](size_t a, size_t b) {
        for (;;) {
            size_t ra = find_root(a);
            size_t rb = find_root(b);
            if (ra == rb) return;

            size_t lo = std::min(ra, rb), hi = std::max(ra, rb);
            locks[lo].lock();
            locks[hi].lock();

            // Verify they are still roots
            if (find_root(ra) != ra || find_root(rb) != rb) {
                locks[hi].unlock();
                locks[lo].unlock();
                continue;
            }

            int sa = parent[ra].load(std::memory_order_relaxed); // negative size
            int sb = parent[rb].load(std::memory_order_relaxed); // negative size
            // Union by size: attach smaller tree (less negative magnitude) to larger
            if (sa > sb) std::swap(ra, rb), std::swap(sa, sb);

            parent[ra].store(sa + sb, std::memory_order_release); // sizes add (stay negative)
            parent[rb].store(static_cast<int>(ra), std::memory_order_release);

            locks[hi].unlock();
            locks[lo].unlock();
            return;
        }
    };

    // Parallel over rows; for each row i only process j>i (upper triangle)
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) unite(i, j);
        }
    });

    // Count roots
    int components = 0;
    for (size_t i = 0; i < N; ++i)
        if (parent[i].load(std::memory_order_acquire) < 0) ++components;

    return components;
}

