int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<std::atomic<size_t>> parent(N);
    for (size_t i = 0; i < N; ++i) parent[i].store(i, std::memory_order_relaxed);

    auto find_root = [&](size_t x) {
        size_t p = parent[x].load(std::memory_order_acquire);
        while (p != x) {
            size_t gp = parent[p].load(std::memory_order_acquire);
            // path halving
            size_t expected = p;
            parent[x].compare_exchange_weak(expected, gp, std::memory_order_acq_rel);
            x = p;
            p = gp;
        }
        return p;
    };

    auto unite = [&](size_t a, size_t b) {
        while (true) {
            size_t ra = find_root(a);
            size_t rb = find_root(b);
            if (ra == rb) return;
