            size_t hi = ra > rb ? ra : rb;
            size_t lo = ra > rb ? rb : ra;
            size_t expected = hi;
            if (parent[hi].compare_exchange_strong(expected, lo, std::memory_order_acq_rel))
                return;
        }
    };

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t row = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[row + j]) unite(i, j);
        }
    });

