    for (size_t i = 0; i < N; ++i) {
        parent[i].store(i, std::memory_order_relaxed);
        rank[i].store(0, std::memory_order_relaxed);
    }

    auto find = [&](size_t x) {
        size_t p = parent[x].load(std::memory_order_acquire);
        while (p != x) {
            size_t gp = parent[p].load(std::memory_order_acquire);
            // path halving
            (void)parent[x].compare_exchange_weak(p, gp, std::memory_order_acq_rel);
            x = p;
            p = gp;
        }
        return x;
    };

    auto unite = [&](size_t a, size_t b) {
        for (;;) {
            size_t ra = find(a);
            size_t rb = find(b);
            if (ra == rb) return;

