*/
int componentCount(std::vector<int> const& A, size_t N) {

generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;
    std::vector<std::atomic<int>> parent(N);
    for (size_t i = 0; i < N; ++i) parent[i].store(static_cast<int>(i), std::memory_order_relaxed);

    auto find_root = [&](int x) {
        int p = parent[x].load(std::memory_order_relaxed);
        while (p != x) {
            int gp = parent[p].load(std::memory_order_relaxed);
            parent[x].store(gp, std::memory_order_relaxed); // path halving
            x = p;
            p = gp;
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        for (;;) {
            int ra = find_root(a);
            int rb = find_root(b);
            if (ra == rb) return;
            int high = ra > rb ? ra : rb;
            int low  = ra ^ rb ^ high;
            int expected = high;
            if (parent[high].compare_exchange_strong(expected, low, std::memory_order_relaxed)) return;
            // else: someone else updated, retry
        }
    };

    // Parallelize over rows; only process upper triangle (i < j)
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) unite(static_cast<int>(i), static_cast<int>(j));
        }
    });

    // Compute roots in parallel
    std::vector<int> roots(N);
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        roots[i] = find_root(static_cast<int>(i));
    });

    // Count unique roots
    std::sort(roots.begin(), roots.end());
    roots.erase(std::unique(roots.begin(), roots.end()), roots.end());
    return static_cast<int>(roots.size());
}

