   output: 2
*/
int componentCount(std::vector<int> const& A, size_t N) {

generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
  if (N == 0) return 0;

  struct DSU {
    std::vector<std::atomic<size_t>> parent;
    std::vector<std::atomic<uint8_t>> rank;

    DSU(size_t n) : parent(n), rank(n) {
      for (size_t i = 0; i < n; ++i) {
        parent[i].store(i, std::memory_order_relaxed);
        rank[i].store(0, std::memory_order_relaxed);
      }
    }

    size_t find(size_t x) {
      // Non-compressing find to avoid heavy synchronization
      size_t p = parent[x].load(std::memory_order_relaxed);
      while (p != x) {
        x = p;
        p = parent[x].load(std::memory_order_relaxed);
      }
      return x;
    }

    void unite(size_t a, size_t b) {
      for (;;) {
        size_t ra = find(a);
        size_t rb = find(b);
        if (ra == rb) return;

        uint8_t rra = rank[ra].load(std::memory_order_relaxed);
        uint8_t rrb = rank[rb].load(std::memory_order_relaxed);

        // Attach lower rank under higher rank
        if (rra < rrb) {
          std::swap(ra, rb);
          std::swap(rra, rrb);
        }

        size_t expected = rb;
        if (parent[rb].compare_exchange_strong(expected, ra,
                                               std::memory_order_acq_rel)) {
          if (rra == rrb) {
            rank[ra].fetch_add(1, std::memory_order_relaxed);
          }
          return;
        }
        // Else some other thread changed rb's parent; retry
      }
    }
  };

  DSU dsu(N);

  // Parallelize over upper triangle (i < j) to avoid duplicate edges
  hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
    size_t base = i * N;
    for (size_t j = i + 1; j < N; ++j) {
      if (A[base + j]) {
        dsu.unite(i, j);
      }
    }
  });

  // Count roots
  int components = 0;
  for (size_t i = 0; i < N; ++i) {
    if (dsu.find(i) == i) ++components;
  }
  return components;
}

