   output: 2
*/
int componentCount(std::vector<int> const& A, size_t N) {

generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    struct DSU {
        std::vector<std::atomic<int>> parent;
        std::vector<std::atomic<int>> rank;

        explicit DSU(size_t n) : parent(n), rank(n) {
            for (size_t i = 0; i < n; ++i) {
                parent[i].store(static_cast<int>(i), std::memory_order_relaxed);
                rank[i].store(0, std::memory_order_relaxed);
            }
        }

        int find(int u) {
            int p = parent[u].load(std::memory_order_relaxed);
            while (p != u) {
                int gp = parent[p].load(std::memory_order_relaxed);
                parent[u].store(gp, std::memory_order_relaxed); // path halving
                u = p;
                p = gp;
            }
            return u;
        }

        void unite(int a, int b) {
            for (;;) {
                int ra = find(a);
                int rb = find(b);
                if (ra == rb) return;

                int rra = rank[ra].load(std::memory_order_relaxed);
                int rrb = rank[rb].load(std::memory_order_relaxed);

                if (rra < rrb) std::swap(ra, rb), std::swap(rra, rrb);

                int expected = rb;
                if (parent[rb].compare_exchange_strong(expected, ra, std::memory_order_acq_rel)) {
                    if (rra == rrb) {
                        rank[ra].fetch_add(1, std::memory_order_relaxed);
                    }
                    return;
                }
                // else: someone else linked rb; retry
            }
        }
    };

    DSU dsu(N);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) dsu.unite(static_cast<int>(i), static_cast<int>(j));
        }
    });

    // Count unique roots
    return hpx::transform_reduce(
        hpx::execution::par, size_t(0), N, 0,
        std::plus<int>(),
        [&](size_t i) { return dsu.find(static_cast<int>(i)) == static_cast<int>(i) ? 1 : 0; }
    );
}

