int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    struct DSU {
        std::vector<std::atomic<size_t>> parent;
        std::vector<std::atomic<unsigned>> rank;

        DSU(size_t n) : parent(n), rank(n) {
            for (size_t i = 0; i < n; ++i) {
                parent[i].store(i, std::memory_order_relaxed);
                rank[i].store(0u, std::memory_order_relaxed);
            }
        }

        size_t find(size_t x) {
            size_t p = parent[x].load(std::memory_order_acquire);
            while (p != x) {
                size_t gp = parent[p].load(std::memory_order_acquire);
                parent[x].compare_exchange_weak(p, gp, std::memory_order_acq_rel); // path halving
                x = p;
                p = gp;
            }
            return x;
        }

        void unite(size_t a, size_t b) {
            while (true) {
                a = find(a);
                b = find(b);
                if (a == b) return;

                // union by rank
                unsigned ra = rank[a].load(std::memory_order_acquire);
                unsigned rb = rank[b].load(std::memory_order_acquire);

                // ensure a has >= rank
                if (ra < rb) std::swap(a, b), std::swap(ra, rb);

                // try to link b under a
                size_t expected = b;
                if (parent[b].compare_exchange_strong(expected, a, std::memory_order_acq_rel)) {
                    if (ra == rb) {
                        // increment rank[a]
                        unsigned r = ra;
                        rank[a].compare_exchange_strong(r, r + 1, std::memory_order_acq_rel);
                    }
                    return;
                }
                // someone else changed parent[b], retry
            }
        }
    };

    DSU dsu(N);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t row = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[row + j] != 0) dsu.unite(i, j);
        }
    });

