    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        roots[i] = dsu.find(i);
    });

    std::sort(roots.begin(), roots.end());
    return int(std::unique(roots.begin(), roots.end()) - roots.begin());
}

