            if (parent[rb].compare_exchange_weak(expected, ra, std::memory_order_relaxed)) {
                if (rka == rkb) {
                    rank[ra].fetch_add(1, std::memory_order_relaxed);
                }
                return;
            }
            // else retry (someone else changed rb's parent)
        }
    };

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j] != 0) {
                unite(static_cast<int>(i), static_cast<int>(j));
            }
        }
    });

    size_t count = 0;
    for (size_t i = 0; i < N; ++i) {
        if (find(static_cast<int>(i)) == static_cast<int>(i)) ++count;
    }
    return static_cast<int>(count);
}

