   output: 2
*/
int componentCount(std::vector<int> const& A, size_t N) {

generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    UnionFind uf(N);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        size_t base = i * N;
        for (size_t j = i + 1; j < N; ++j) {
            if (A[base + j]) uf.unite(static_cast<int>(i), static_cast<int>(j));
        }
    });

    auto first = hpx::make_counting_iterator<size_t>(0);
    auto last  = hpx::make_counting_iterator<size_t>(N);
    int comps = hpx::transform_reduce(
        hpx::execution::par, first, last, 0, std::plus<int>{},
        [&](size_t i) { return uf.is_root(static_cast<int>(i)) ? 1 : 0; });

    return comps;
}

