int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {
    if (source < 0 || dest < 0 || static_cast<size_t>(source) >= N || static_cast<size_t>(dest) >= N) return -1;
    if (source == dest) return 0;

    std::vector<std::atomic<bool>> visited(N);
    for (size_t i = 0; i < N; ++i) visited[i].store(false, std::memory_order_relaxed);
    visited[source].store(true, std::memory_order_relaxed);

    std::vector<size_t> frontier;
    frontier.push_back(static_cast<size_t>(source));

    int dist = 0;

    while (!frontier.empty()) {
        ++dist;

        std::vector<std::atomic<bool>> next(N);
        for (size_t i = 0; i < N; ++i) next[i].store(false, std::memory_order_relaxed);
        std::atomic<bool> found(false);

        hpx::for_loop(hpx::execution::par, size_t(0), frontier.size(), [&](size_t i) {
            size_t u = frontier[i];
            size_t row = u * N;
            for (size_t v = 0; v < N; ++v) {
                if (A[row + v]) {
                    bool expected = false;
                    if (visited[v].compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                        next[v].store(true, std::memory_order_relaxed);
                        if (static_cast<int>(v) == dest) {
                            found.store(true, std::memory_order_relaxed);
                        }
                    }
                }
            }
        });

        if (found.load(std::memory_order_relaxed)) return dist;

        frontier.clear();
        frontier.reserve(N);
        for (size_t v = 0; v < N; ++v)
            if (next[v].load(std::memory_order_relaxed)) frontier.push_back(v);
    }

    return -1;
}

