    if (source < 0 || dest < 0 || (size_t)source >= N || (size_t)dest >= N) return -1;

    std::vector<std::atomic<bool>> visited(N);
    for (auto& v : visited) v.store(false, std::memory_order_relaxed);
    visited[(size_t)source].store(true, std::memory_order_relaxed);

    std::vector<int> current{source};
    int dist = 0;

    while (!current.empty()) {
        ++dist;
        std::vector<int> next;
        hpx::mutex mtx;
        std::atomic<bool> reached{false};

        hpx::for_each(hpx::execution::par, current.begin(), current.end(), [&](int u) {
