int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {

generated_output:
int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {
    if (source == dest) return 0;
    if (N == 0) return -1;

    std::vector<unsigned char> visited(N, 0), frontier(N, 0), next_frontier(N, 0);
    frontier[source] = 1;
    int dist = 0;

    while (true) {
        if (frontier[dest]) return dist;

        // Mark current frontier as visited
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            if (frontier[i]) visited[i] = 1;
        });

        // Build next frontier in parallel: nodes not visited that have any neighbor in frontier
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t v) {
            if (visited[v]) {
                next_frontier[v] = 0;
                return;
            }
            int hit = 0;
            for (size_t u = 0; u < N; ++u) {
                if (frontier[u] && A[u * N + v]) { hit = 1; break; }
            }
            next_frontier[v] = hit ? 1 : 0;
        });

        // Check if expansion stalled
        bool any = false;
        for (size_t i = 0; i < N; ++i) {
            if (next_frontier[i]) { any = true; break; }
        }
        if (!any) return -1;

        frontier.swap(next_frontier);

        // Clear next_frontier in parallel for next iteration
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) { next_frontier[i] = 0; });

        ++dist;
    }
}

