                }
            });

        if (found.load(std::memory_order_relaxed)) return answer.load(std::memory_order_relaxed);
        frontier.swap(next);
    }

    return found.load(std::memory_order_relaxed) ? answer.load(std::memory_order_relaxed) : -1;
}

