int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {
    if (source == dest) return 0;
    if (N == 0) return -1;

    std::vector<std::atomic<bool>> visited(N);
    for (size_t i = 0; i < N; ++i) visited[i].store(false, std::memory_order_relaxed);
    visited[source].store(true, std::memory_order_relaxed);

    std::vector<int> frontier;
    frontier.push_back(source);

    int dist = 0;

    while (!frontier.empty()) {
        ++dist;

        std::size_t P = std::max<std::size_t>(1, hpx::get_num_worker_threads());
        std::vector<std::vector<int>> tls(P);
        std::atomic<bool> found{false};

        hpx::for_loop(hpx::execution::par, std::size_t(0), frontier.size(),
            [&](std::size_t i) {
                int u = frontier[i];
                std::size_t tid = static_cast<std::size_t>(hpx::get_worker_thread_num());
                auto& out = tls[tid];

                std::size_t row = static_cast<std::size_t>(u) * N;
                for (std::size_t v = 0; v < N; ++v) {
                    if (A[row + v] == 0) continue;

                    if (!visited[v].load(std::memory_order_relaxed)) {
                        bool expected = false;
                        if (visited[v].compare_exchange_strong(expected, true, std::memory_order_relaxed)) {
                            if (static_cast<int>(v) == dest) {
                                found.store(true, std::memory_order_relaxed);
                            }
                            out.push_back(static_cast<int>(v));
                        }
                    }
                }
            });

        if (found.load(std::memory_order_relaxed)) return dist;

        std::size_t total = 0;
        for (auto const& v : tls) total += v.size();
        std::vector<int> next;
        next.reserve(total);
        for (auto& v : tls) {
            next.insert(next.end(), v.begin(), v.end());
        }

        frontier.swap(next);
    }

    return -1;
}

