int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {
    if (source == dest) return 0;
    if (source < 0 || dest < 0 || (size_t)source >= N || (size_t)dest >= N) return -1;

    std::vector<std::atomic<int>> dist(N);
    for (size_t i = 0; i < N; ++i) dist[i].store(-1, std::memory_order_relaxed);
    dist[source].store(0, std::memory_order_relaxed);

    std::vector<size_t> frontier{static_cast<size_t>(source)};
    std::atomic<bool> found{false};

    while (!frontier.empty() && !found.load(std::memory_order_relaxed)) {
        std::vector<size_t> next;
        next.reserve(N);
        hpx::mutex push_mtx;

        hpx::for_each(hpx::execution::par, frontier.begin(), frontier.end(),
            [&](size_t u) {
                int du = dist[u].load(std::memory_order_relaxed);
                for (size_t v = 0; v < N && !found.load(std::memory_order_relaxed); ++v) {
                    if (A[u * N + v]) {
                        int expected = -1;
                        if (dist[v].compare_exchange_strong(expected, du + 1, std::memory_order_relaxed)) {
                            if ((int)v == dest) {
                                found.store(true, std::memory_order_relaxed);
                            }
                            std::scoped_lock<hpx::mutex> lk(push_mtx);
                            next.push_back(v);
                        }
                    }
                }
            });

        if (found.load(std::memory_order_relaxed)) break;
        frontier = std::move(next);
    }

    return dist[dest].load(std::memory_order_relaxed);
}

