    std::vector<char> visited(N, 0);
    visited[source] = 1;

    std::vector<int> frontier{source};
    int dist = 0;

    // Pre-build index vector once for parallel loops
    std::vector<size_t> indices(N);
    std::iota(indices.begin(), indices.end(), 0);

    while (!frontier.empty()) {
        ++dist;

        std::vector<char> mark(N, 0);

        // For each vertex v in parallel, check if any u in current frontier connects to v
        hpx::ranges::for_each(hpx::execution::par, indices, [&](size_t v) {
