        std::vector<int> next_frontier;
        next_frontier.reserve(frontier.size() * 2);
        for (size_t v = 0; v < N; ++v) {
            if (mark[v]) {
                visited[v] = 1;
                next_frontier.push_back(static_cast<int>(v));
            }
        }
        frontier.swap(next_frontier);
    }

    return -1; // unreachable
}

