generated_output:
int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {
    if (source == dest) return 0;
    if (source < 0 || dest < 0 || static_cast<size_t>(source) >= N || static_cast<size_t>(dest) >= N) return -1;

    std::vector<std::atomic_bool> visited(N);
    for (auto& v : visited) v.store(false, std::memory_order_relaxed);

    std::vector<char> frontier(N, 0);
    frontier[source] = 1;
    visited[source].store(true, std::memory_order_relaxed);

    std::vector<std::atomic_bool> next_marks(N);
    for (auto& m : next_marks) m.store(false, std::memory_order_relaxed);

    int dist = 0;
    while (true) {
        // Check if destination is in current frontier
        if (frontier[dest]) return dist;

        // Expand frontier in parallel
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t u) {
