            for (size_t v = 0; v < N; ++v) {
                if (A[base + v] != 0) {
                    if (!visited[v].load(std::memory_order_relaxed)) {
                        if (!visited[v].exchange(true, std::memory_order_acq_rel)) {
                            next_marks[v].store(true, std::memory_order_release);
                        }
                    }
                }
            }
        });

        // Build next frontier
        bool any = false;
        for (size_t i = 0; i < N; ++i) {
            bool mark = next_marks[i].exchange(false, std::memory_order_acq_rel);
            frontier[i] = mark ? 1 : 0;
            any |= mark;
        }

        if (!any) break; // no more nodes to explore
        ++dist;
    }

    return -1;
}

